param(
    [string]$ProjectRoot = (Get-Location).Path
)

$ErrorActionPreference = "Stop"
$ProjectRoot = (Resolve-Path $ProjectRoot).Path

$SrcDir = Join-Path $ProjectRoot "src"
$AutomationDir = Join-Path $ProjectRoot "automation"
$DatabasePath = Join-Path $ProjectRoot "database\polymarket.db"
$EnginePath = Join-Path $SrcDir "historical_timeline_engine.py"
$RunnerPath = Join-Path $AutomationDir "run_historical_timeline.ps1"
$LockPath = Join-Path $ProjectRoot "logs\automation\platform.lock"

foreach ($Required in @($SrcDir, $AutomationDir, $DatabasePath)) {
    if (-not (Test-Path $Required)) {
        throw "Required project item not found: $Required"
    }
}

if (Test-Path $LockPath) {
    throw "A platform automation lock exists. Finish the active platform run before installing this module."
}

$Timestamp = Get-Date -Format "yyyyMMdd_HHmmss"
$BackupDir = Join-Path $AutomationDir "backups\historical_timeline_$Timestamp"
New-Item -ItemType Directory -Path $BackupDir -Force | Out-Null

Copy-Item $DatabasePath (Join-Path $BackupDir "polymarket.db") -Force
foreach ($File in @($EnginePath, $RunnerPath)) {
    if (Test-Path $File) {
        Copy-Item $File (Join-Path $BackupDir ([IO.Path]::GetFileName($File))) -Force
    }
}

$Encoded = ""
$Bytes = [Convert]::FromBase64String($Encoded)
[System.IO.File]::WriteAllBytes($EnginePath, $Bytes)

$Runner = @'
param(
    [string]$ProjectRoot = (Resolve-Path (Join-Path $PSScriptRoot "..")).Path
)

$ErrorActionPreference = "Stop"
Push-Location $ProjectRoot
try {
    python -m src.historical_timeline_engine
    if ($LASTEXITCODE -ne 0) {
        throw "Historical Timeline Engine failed."
    }
}
finally {
    Pop-Location
}
'@

[System.IO.File]::WriteAllText(
    $RunnerPath,
    $Runner,
    (New-Object System.Text.UTF8Encoding($false))
)

python -m py_compile $EnginePath
if ($LASTEXITCODE -ne 0) {
    throw "Historical Timeline Engine failed Python compilation. Backup: $BackupDir"
}

Write-Host ""
Write-Host "Running Historical Timeline Engine v1.0..."
python -m src.historical_timeline_engine
if ($LASTEXITCODE -ne 0) {
    throw "Historical Timeline Engine failed. Backup: $BackupDir"
}

Write-Host ""
Write-Host "HISTORICAL TIMELINE MODULE INSTALLED SUCCESSFULLY"
Write-Host "Engine: $EnginePath"
Write-Host "Runner: $RunnerPath"
Write-Host "Backup: $BackupDir"
Write-Host ""
Write-Host "Future isolated runs:"
Write-Host "  .\automation\run_historical_timeline.ps1"
